CREATE OR REPLACE FUNCTION public.next_sales_number(p_client text,p_type text,p_date date) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid:=public.active_tenant_id(); code text; n bigint; fmt text; fallback text; BEGIN IF p_type NOT IN ('order','invoice','quotation') OR NOT public.can_access_tenant_module(tid,CASE WHEN p_type='quotation' THEN 'quotations' ELSE 'orders' END) THEN RAISE EXCEPTION 'Modul tidak berizin'; END IF; code:=regexp_replace(upper(btrim(p_client)),'[^A-Z0-9]','','g'); IF code='' OR p_date IS NULL THEN RAISE EXCEPTION 'Client dan tanggal wajib'; END IF; SELECT doc_numbering->>p_type,sales_numbering->>p_type INTO fmt,fallback FROM public.tenant_settings WHERE tenant_id=tid; IF fmt IS NULL OR fmt='{SEQ}/SDY/INV/{CLIENT}/{MM}{YYYY}' THEN fmt:=fallback; END IF; IF fmt IS NULL OR position('{SEQ}' in fmt)=0 AND position('{urut}' in fmt)=0 THEN RAISE EXCEPTION 'Format nomor harus memuat {SEQ} atau {urut}'; END IF; INSERT INTO public.document_sequences(tenant_id,client_code,document_type,sequence) VALUES(tid,code,p_type,1) ON CONFLICT(tenant_id,client_code,document_type) DO UPDATE SET sequence=public.document_sequences.sequence+1 RETURNING sequence INTO n; RETURN replace(replace(replace(replace(replace(replace(fmt,'{CLIENT}',code),'{KODE_CLIENT}',code),'{YYYY}',to_char(p_date,'YYYY')),'{MM}',to_char(p_date,'MM')),'{SEQ}',n::text),'{urut}',n::text); END $$;
COMMENT ON COLUMN public.tenant_settings.doc_numbering IS 'Per-tenant sales numbering overrides; legacy Sedyain pattern ignored for newly issued documents';
COMMENT ON COLUMN public.tenant_settings.sales_numbering IS 'Sales numbering fallback defaults for missing doc_numbering keys';
CREATE OR REPLACE FUNCTION public.suggest_invoice_number(p_client_name text,p_invoice_date date) RETURNS text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid:=public.active_tenant_id(); code text; n bigint; fmt text; fallback text; BEGIN IF NOT public.can_access('orders') THEN RAISE EXCEPTION 'Tidak berizin'; END IF; code:=regexp_replace(upper(btrim(p_client_name)),'[^A-Z0-9]','','g'); SELECT COALESCE(sequence,0)+1 INTO n FROM public.document_sequences WHERE tenant_id=tid AND client_code=code AND document_type='invoice'; n:=COALESCE(n,1); SELECT doc_numbering->>'invoice',sales_numbering->>'invoice' INTO fmt,fallback FROM public.tenant_settings WHERE tenant_id=tid; IF fmt IS NULL OR fmt='{SEQ}/SDY/INV/{CLIENT}/{MM}{YYYY}' THEN fmt:=fallback; END IF; RETURN replace(replace(replace(replace(replace(replace(fmt,'{CLIENT}',code),'{KODE_CLIENT}',code),'{YYYY}',to_char(p_invoice_date,'YYYY')),'{MM}',to_char(p_invoice_date,'MM')),'{SEQ}',n::text),'{urut}',n::text); END $$;